with d as (select '{"lang":{"id":"python","name":"Python","mono":"Py","color":"#3776AB","accent":"#FFD43B","description":"Penulisannya singkat dan mudah dibaca. Cocok untuk pemula yang baru mulai belajar.","position":0},"units":[{"id":1,"title":"Pengenalan Pemrograman","position":0},{"id":2,"title":"Variabel dan Tipe Data","position":1},{"id":3,"title":"Percabangan","position":2},{"id":4,"title":"Perulangan","position":3}],"lessons":[{"id":101,"unit_id":1,"title":"Apa itu program?","type":"mc","duration_min":4,"xp":15,"published":true,"position":0,"material":{"intro":"Program adalah sekumpulan perintah yang ditulis agar komputer mengerjakan sesuatu. Perintah itu ditulis memakai bahasa pemrograman.","points":[["Komputer hanya mengikuti perintah","Komputer tidak bisa menebak maksud kita. Perintah harus jelas dan berurutan."],["Bahasa pemrograman","Cara menulis perintah yang dimengerti manusia dan bisa diterjemahkan ke komputer, misalnya Python, Java, dan C."],["Kenapa Python?","Penulisannya singkat dan mirip bahasa Inggris, jadi cocok untuk pemula. Materi di Sinau memakai Python."]],"code":"print(\"Halo, Sinau!\")\n# output: Halo, Sinau!","tip":"Membuat program mirip menulis resep: langkahnya harus urut dan tidak boleh ada yang terlewat."}},{"id":102,"unit_id":1,"title":"Algoritma dan flowchart","type":"order","duration_min":5,"xp":15,"published":true,"position":1,"material":{"intro":"Algoritma adalah langkah-langkah logis untuk menyelesaikan masalah. Flowchart adalah gambar dari algoritma tersebut.","points":[["Ciri algoritma","Ada input dan output, langkahnya jelas, dan pasti selesai."],["Oval","Mulai atau selesai."],["Jajar genjang","Input atau output data."],["Persegi panjang","Proses atau perhitungan."],["Belah ketupat","Keputusan atau percabangan (ya/tidak)."]],"tip":"Tulis algoritmanya dulu dengan bahasa sehari-hari, baru ubah menjadi kode."}},{"id":103,"unit_id":1,"title":"Program pertamamu","type":"mc","duration_min":4,"xp":15,"published":true,"position":2,"material":{"intro":"Perintah pertama yang biasa dipelajari adalah print(), yaitu menampilkan sesuatu ke layar.","points":[["print()","Menampilkan teks atau angka ke layar."],["Teks memakai tanda kutip","Teks ditulis di antara tanda kutip, misalnya \"Halo\"."],["Angka tanpa tanda kutip","print(10) menampilkan 10, print(2 + 3) menampilkan 5."],["Satu perintah per baris","Python membaca program dari atas ke bawah."]],"code":"print(\"Halo, dunia!\")\nprint(2 + 3)\n# output:\n# Halo, dunia!\n# 5","tip":"print(\"2 + 3\") menampilkan teks 2 + 3, sedangkan print(2 + 3) menampilkan hasilnya, yaitu 5."}},{"id":104,"unit_id":1,"title":"Komentar dan error","type":"mc","duration_min":5,"xp":15,"published":true,"position":3,"material":{"intro":"Komentar adalah catatan di dalam kode yang tidak dijalankan. Error adalah kesalahan yang membuat program gagal berjalan.","points":[["Komentar","Diawali tanda #. Gunanya menjelaskan maksud kode untuk manusia."],["Syntax error","Penulisan kode salah, misalnya tanda kurung atau tanda kutip tidak ditutup."],["Name error","Memakai nama yang belum dibuat, misalnya variabel yang salah ketik."],["Baca pesan error","Pesan error memberi tahu baris dan jenis kesalahannya."]],"code":"# ini komentar, tidak dijalankan\nprint(\"Halo\")\nprint(\"Sinau\"   # SyntaxError: kurung tidak ditutup","tip":"Error itu wajar. Baca pesannya, cari baris yang disebut, lalu perbaiki satu per satu."}},{"id":201,"unit_id":2,"title":"Variabel","type":"mc","duration_min":5,"xp":15,"published":true,"position":0,"material":{"intro":"Variabel adalah tempat menyimpan nilai, seperti kotak yang diberi nama.","points":[["Membuat variabel","Tulis nama, tanda =, lalu nilainya. Contoh: umur = 19."],["Nilai bisa diganti","Variabel yang sama bisa diisi nilai baru. Nilai terakhir yang dipakai."],["Aturan nama","Tidak boleh diawali angka dan tidak boleh ada spasi. Pakai garis bawah, misalnya nama_lengkap."]],"code":"nama = \"Zidney\"\numur = 19\numur = 20\nprint(nama, umur)\n# output: Zidney 20","tip":"Beri nama variabel yang menjelaskan isinya, misalnya total_harga, bukan x."}},{"id":202,"unit_id":2,"title":"Tipe data","type":"mc","duration_min":5,"xp":15,"published":true,"position":1,"material":{"intro":"Setiap nilai punya tipe data. Tipe data menentukan apa yang bisa dilakukan pada nilai itu.","points":[["int","Bilangan bulat, contoh: 20."],["float","Bilangan desimal, contoh: 3.14."],["str (string)","Teks di antara tanda kutip, contoh: \"Sinau\"."],["bool","Nilai logika: True atau False."]],"code":"umur = 20         # int\nipk = 3.75        # float\nnama = \"Sinau\"    # str\naktif = True      # bool\nprint(type(ipk))  # <class ''float''>","tip":"Pakai type() untuk mengecek tipe data sebuah nilai."}},{"id":203,"unit_id":2,"title":"Input dan output","type":"order","duration_min":5,"xp":15,"published":true,"position":2,"material":{"intro":"Input adalah data yang dimasukkan pengguna, output adalah hasil yang ditampilkan program.","points":[["input()","Meminta pengguna mengetik sesuatu. Hasilnya selalu berupa teks (str)."],["int() dan float()","Mengubah teks dari input() menjadi angka agar bisa dihitung."],["print()","Menampilkan hasil. Beberapa nilai bisa dipisah dengan koma."]],"code":"nama = input(\"Nama kamu: \")\numur = int(input(\"Umur: \"))\nprint(\"Halo\", nama)\nprint(\"Tahun depan umurmu\", umur + 1)","tip":"Lupa mengubah input() ke int() adalah kesalahan paling sering pemula. \"19\" + 1 akan error."}},{"id":204,"unit_id":2,"title":"Operator aritmatika","type":"mc","duration_min":5,"xp":15,"published":true,"position":3,"material":{"intro":"Operator aritmatika dipakai untuk menghitung, seperti kalkulator.","points":[["+  -  *  /","Tambah, kurang, kali, dan bagi. Hasil / selalu desimal."],["//","Pembagian bulat, membuang angka di belakang koma."],["%","Sisa bagi (modulo). Sering dipakai untuk cek ganjil atau genap."],["**","Pangkat, contoh 2 ** 3 = 8."]],"code":"print(7 / 2)   # 3.5\nprint(7 // 2)  # 3\nprint(7 % 2)   # 1\nprint(2 ** 3)  # 8","tip":"Urutan hitung sama seperti matematika: kurung, pangkat, kali/bagi, lalu tambah/kurang."}},{"id":301,"unit_id":3,"title":"Perbandingan dan logika","type":"result","duration_min":5,"xp":15,"published":true,"position":0,"material":{"intro":"Sebelum membuat percabangan, kita perlu kondisi. Kondisi adalah pernyataan yang hasilnya True atau False.","points":[["Operator perbandingan","== sama dengan, != tidak sama, >, <, >=, <=."],["and","True jika kedua kondisi benar."],["or","True jika minimal salah satu kondisi benar."],["not","Membalik nilai: not True menjadi False."]],"code":"nilai = 80\nprint(nilai >= 75)              # True\nprint(nilai > 90 or nilai == 80) # True\nprint(nilai > 70 and nilai < 75) # False","tip":"Jangan tertukar: = untuk mengisi variabel, == untuk membandingkan."}},{"id":302,"unit_id":3,"title":"If dan else","type":"mc","duration_min":5,"xp":15,"published":true,"position":1,"material":{"intro":"Percabangan membuat program memilih jalan berdasarkan kondisi.","points":[["if","Blok di bawahnya dijalankan jika kondisi True."],["else","Dijalankan jika kondisi if False."],["Indentasi","Baris di dalam if atau else harus menjorok ke dalam (4 spasi)."],["Titik dua","Setiap if dan else diakhiri tanda titik dua (:)."]],"code":"nilai = 70\nif nilai >= 75:\n    print(\"Lulus\")\nelse:\n    print(\"Belum lulus\")\n# output: Belum lulus","tip":"Lupa titik dua atau lupa indentasi adalah penyebab error paling umum di percabangan."}},{"id":303,"unit_id":3,"title":"Elif: banyak pilihan","type":"mc","duration_min":6,"xp":15,"published":true,"position":2,"material":{"intro":"Kalau pilihannya lebih dari dua, gunakan elif (singkatan dari else if).","points":[["if","Kondisi pertama yang dicek."],["elif","Dicek jika kondisi sebelumnya False. Boleh lebih dari satu."],["else","Dijalankan jika semua kondisi False."],["Urutan penting","Begitu satu kondisi True, sisanya dilewati."]],"code":"nilai = 75\nif nilai >= 85:\n    print(\"A\")\nelif nilai >= 70:\n    print(\"B\")\nelif nilai >= 55:\n    print(\"C\")\nelse:\n    print(\"D\")\n# output: B","tip":"Susun kondisi dari yang paling ketat (nilai terbesar) ke yang paling longgar."}},{"id":304,"unit_id":3,"title":"Percabangan bersarang","type":"mc","duration_min":6,"xp":15,"published":true,"position":3,"material":{"intro":"Percabangan bersarang adalah if di dalam if. Dipakai jika keputusan kedua bergantung pada keputusan pertama.","points":[["If luar","Dicek lebih dulu."],["If dalam","Hanya dicek jika if luar bernilai True."],["Perhatikan indentasi","Kedalaman indentasi menunjukkan if mana yang menjadi induknya."]],"code":"hadir = True\nnilai = 80\nif hadir:\n    if nilai >= 75:\n        print(\"Lulus\")\n    else:\n        print(\"Remedial\")\nelse:\n    print(\"Tidak boleh ujian\")","tip":"Jika bersarang terlalu dalam, coba sederhanakan dengan and, misalnya: if hadir and nilai >= 75."}},{"id":401,"unit_id":4,"title":"Perulangan for","type":"mc","duration_min":6,"xp":15,"published":true,"position":0,"material":{"intro":"Perulangan for menjalankan perintah berulang kali sebanyak yang ditentukan.","points":[["range(n)","Menghasilkan 0, 1, …, n−1."],["range(a, b)","Menghasilkan a sampai b−1 (b tidak ikut)."],["Variabel perulangan","Berisi nilai saat itu di setiap putaran, biasanya dinamai i."]],"code":"for i in range(1, 4):\n    print(\"Putaran ke-\", i)\n# output:\n# Putaran ke- 1\n# Putaran ke- 2\n# Putaran ke- 3","tip":"Pakai for jika jumlah pengulangannya sudah diketahui."}},{"id":402,"unit_id":4,"title":"Perulangan while","type":"mc","duration_min":6,"xp":15,"published":true,"position":1,"material":{"intro":"Perulangan while menjalankan perintah selama kondisinya masih True.","points":[["Kondisi dicek setiap putaran","Jika False, perulangan berhenti."],["Ubah nilai di dalam loop","Kalau tidak, kondisi tidak pernah False dan program berjalan terus (infinite loop)."],["Kapan pakai while?","Saat jumlah pengulangan belum pasti, misalnya menunggu input yang benar."]],"code":"n = 3\nwhile n > 0:\n    print(n)\n    n = n - 1\nprint(\"Selesai!\")\n# output: 3 2 1 Selesai!","tip":"Selalu pastikan ada baris yang membuat kondisi while suatu saat menjadi False."}},{"id":403,"unit_id":4,"title":"Break dan continue","type":"mc","duration_min":5,"xp":15,"published":true,"position":2,"material":{"intro":"break dan continue mengatur jalannya perulangan dari dalam.","points":[["break","Menghentikan perulangan saat itu juga."],["continue","Melewati sisa perintah pada putaran ini, lalu lanjut ke putaran berikutnya."],["Biasanya dipakai dengan if","Contoh: hentikan perulangan jika data yang dicari sudah ketemu."]],"code":"for i in range(1, 6):\n    if i == 3:\n        continue\n    if i == 5:\n        break\n    print(i)\n# output: 1 2 4","tip":"break keluar dari perulangan, continue hanya melompati satu putaran."}},{"id":404,"unit_id":4,"title":"Studi kasus perulangan","type":"order","duration_min":7,"xp":15,"published":true,"position":3,"material":{"intro":"Mari gabungkan input, percabangan, dan perulangan dalam satu program kecil.","points":[["Kasus","Hitung rata-rata nilai dari beberapa mahasiswa, lalu tentukan lulus atau tidak."],["Langkah 1","Siapkan variabel total = 0."],["Langkah 2","Ulangi input nilai sebanyak jumlah mahasiswa sambil menambah total."],["Langkah 3","Hitung rata-rata, lalu cek dengan if."]],"code":"jumlah = 3\ntotal = 0\nfor i in range(jumlah):\n    nilai = int(input(\"Nilai: \"))\n    total = total + nilai\nrata = total / jumlah\nif rata >= 75:\n    print(\"Rata-rata\", rata, \"lulus\")\nelse:\n    print(\"Rata-rata\", rata, \"belum lulus\")","tip":"Pecah masalah besar menjadi langkah kecil: siapkan data, ulangi, hitung, lalu putuskan."}}],"questions":[{"lesson_id":101,"position":0,"type":"mc","prompt":"Apa yang dimaksud dengan program?","options":{"opts":["Perangkat keras komputer","Sekumpulan perintah agar komputer mengerjakan sesuatu","Gambar di layar","Koneksi internet"]},"answer":1,"explanation":"Program adalah kumpulan perintah yang dijalankan komputer secara berurutan."},{"lesson_id":101,"position":1,"type":"mc","prompt":"Manakah yang termasuk bahasa pemrograman?","options":{"opts":["Microsoft Word","Python","Windows","Google Chrome"]},"answer":1,"explanation":"Python adalah bahasa pemrograman. Yang lain adalah aplikasi atau sistem operasi."},{"lesson_id":101,"position":2,"type":"mc","prompt":"Mengapa perintah dalam program harus jelas dan berurutan?","options":{"opts":["Agar program terlihat panjang","Karena komputer hanya mengikuti perintah apa adanya","Supaya komputer bisa menebak sendiri","Agar internet lebih cepat"]},"answer":1,"explanation":"Komputer tidak bisa menebak maksud kita, ia hanya menjalankan perintah persis seperti yang ditulis."},{"lesson_id":102,"position":0,"type":"mc","prompt":"Simbol flowchart untuk keputusan (ya/tidak) adalah …","options":{"opts":["Oval","Persegi panjang","Belah ketupat","Jajar genjang"]},"answer":2,"explanation":"Belah ketupat dipakai untuk kondisi yang jawabannya ya atau tidak."},{"lesson_id":102,"position":1,"type":"mc","prompt":"Simbol oval pada flowchart menandakan …","options":{"opts":["Proses","Mulai atau selesai","Input","Keputusan"]},"answer":1,"explanation":"Oval adalah simbol terminal, yaitu awal dan akhir algoritma."},{"lesson_id":102,"position":2,"type":"order","prompt":"Susun algoritma menghitung luas persegi panjang","options":{"blocks":["Mulai","Masukkan panjang dan lebar","luas = panjang × lebar","Tampilkan luas","Selesai"],"pool":[2,4,0,3,1]},"answer":[0,1,2,3,4],"explanation":"Mulai → input → proses → output → selesai."},{"lesson_id":103,"position":0,"type":"mc","prompt":"Perintah untuk menampilkan tulisan ke layar di Python adalah …","options":{"opts":["show()","print()","write()","display()"]},"answer":1,"explanation":"Di Python, print() dipakai untuk menampilkan output."},{"lesson_id":103,"position":1,"type":"mc","prompt":"Apa output kode berikut?","options":{"code":"print(4 + 6)","opts":["4 + 6","10","46","Error"]},"answer":1,"explanation":"Tanpa tanda kutip, Python menghitung 4 + 6 = 10."},{"lesson_id":103,"position":2,"type":"mc","prompt":"Apa output kode berikut?","options":{"code":"print(\"4 + 6\")","opts":["10","4 + 6","\"4 + 6\"","Error"]},"answer":1,"explanation":"Karena diapit tanda kutip, 4 + 6 dianggap teks dan ditampilkan apa adanya."},{"lesson_id":104,"position":0,"type":"mc","prompt":"Komentar di Python diawali dengan tanda …","options":{"opts":["//","#","--","/*"]},"answer":1,"explanation":"Di Python, komentar satu baris diawali tanda #."},{"lesson_id":104,"position":1,"type":"mc","prompt":"Kode berikut menghasilkan error apa?","options":{"code":"print(\"Halo\"","opts":["Tidak error","SyntaxError","NameError","Output Halo"]},"answer":1,"explanation":"Tanda kurung tidak ditutup, jadi penulisan kodenya salah (SyntaxError)."},{"lesson_id":104,"position":2,"type":"mc","prompt":"Apa yang terjadi pada baris komentar saat program dijalankan?","options":{"opts":["Ditampilkan ke layar","Diabaikan oleh Python","Membuat error","Dijalankan dua kali"]},"answer":1,"explanation":"Komentar hanya catatan untuk manusia, Python mengabaikannya."},{"lesson_id":201,"position":0,"type":"mc","prompt":"Berapa nilai x setelah kode ini dijalankan?","options":{"code":"x = 5\nx = x + 3\nx = x * 2","opts":["8","10","16","13"]},"answer":2,"explanation":"x = 5 → 8 → 16."},{"lesson_id":201,"position":1,"type":"mc","prompt":"Manakah nama variabel yang benar di Python?","options":{"opts":["2nilai","nilai akhir","nilai_akhir","nilai-akhir"]},"answer":2,"explanation":"Nama variabel tidak boleh diawali angka, tidak boleh ada spasi, dan tidak boleh memakai tanda minus."},{"lesson_id":201,"position":2,"type":"mc","prompt":"Apa output kode berikut?","options":{"code":"kota = \"Malang\"\nkota = \"Batu\"\nprint(kota)","opts":["Malang","Batu","Malang Batu","Error"]},"answer":1,"explanation":"Nilai variabel diganti, jadi yang tersimpan adalah nilai terakhir: Batu."},{"lesson_id":202,"position":0,"type":"mc","prompt":"Tipe data untuk nilai 3.14 adalah …","options":{"opts":["int","float","str","bool"]},"answer":1,"explanation":"Bilangan desimal bertipe float."},{"lesson_id":202,"position":1,"type":"mc","prompt":"Manakah yang bertipe string?","options":{"opts":["42","True","\"42\"","4.2"]},"answer":2,"explanation":"Nilai yang diapit tanda kutip adalah string, meskipun isinya angka."},{"lesson_id":202,"position":2,"type":"mc","prompt":"Nilai True dan False termasuk tipe data …","options":{"opts":["int","str","bool","float"]},"answer":2,"explanation":"True dan False adalah nilai logika bertipe bool (boolean)."},{"lesson_id":203,"position":0,"type":"mc","prompt":"Hasil dari input() selalu bertipe …","options":{"opts":["int","float","str","bool"]},"answer":2,"explanation":"input() selalu mengembalikan teks (str), meskipun yang diketik angka."},{"lesson_id":203,"position":1,"type":"mc","prompt":"Fungsi untuk mengubah teks \"25\" menjadi bilangan bulat adalah …","options":{"opts":["str()","int()","print()","input()"]},"answer":1,"explanation":"int(\"25\") menghasilkan angka 25."},{"lesson_id":203,"position":2,"type":"order","prompt":"Susun program yang meminta dua angka lalu menampilkan jumlahnya","options":{"blocks":["a = int(input(\"Angka 1: \"))","b = int(input(\"Angka 2: \"))","hasil = a + b","print(\"Jumlah:\", hasil)"],"pool":[2,0,3,1]},"answer":[0,1,2,3],"explanation":"Ambil input pertama dan kedua, hitung jumlahnya, lalu tampilkan."},{"lesson_id":204,"position":0,"type":"mc","prompt":"Apa hasil dari 10 % 3?","options":{"opts":["3","1","3.33","0"]},"answer":1,"explanation":"10 dibagi 3 hasilnya 3 sisa 1, jadi 10 % 3 = 1."},{"lesson_id":204,"position":1,"type":"mc","prompt":"Apa hasil dari 9 // 2?","options":{"opts":["4.5","4","5","1"]},"answer":1,"explanation":"// adalah pembagian bulat: 9 ÷ 2 = 4,5 lalu dibulatkan ke bawah menjadi 4."},{"lesson_id":204,"position":2,"type":"mc","prompt":"Apa output kode berikut?","options":{"code":"print(2 + 3 * 4)","opts":["20","14","24","9"]},"answer":1,"explanation":"Perkalian dihitung dulu: 3 × 4 = 12, lalu 2 + 12 = 14."},{"lesson_id":301,"position":0,"type":"mc","prompt":"Operator untuk mengecek \"sama dengan\" adalah …","options":{"opts":["=","==","!=","=>"]},"answer":1,"explanation":"== membandingkan dua nilai, sedangkan = dipakai untuk mengisi variabel."},{"lesson_id":301,"position":1,"type":"mc","prompt":"Lengkapi tabel hasil a and b pada baris yang kosong.","options":{"table":{"head":["a","b","a and b"],"rows":[["True","True","True"],["True","False","?"],["False","True","False"],["False","False","False"]]},"opts":["True","False"]},"answer":1,"explanation":"and hanya True jika keduanya True. Karena b False, hasilnya False."},{"lesson_id":301,"position":2,"type":"mc","prompt":"Jika x = 5, apa hasil dari x > 3 or x > 10?","options":{"opts":["True","False","5","Error"]},"answer":0,"explanation":"x > 3 bernilai True. Dengan or, cukup satu yang True agar hasilnya True."},{"lesson_id":302,"position":0,"type":"mc","prompt":"Apa output kode berikut?","options":{"code":"umur = 17\nif umur >= 17:\n    print(\"Boleh membuat KTP\")\nelse:\n    print(\"Belum boleh\")","opts":["Boleh membuat KTP","Belum boleh","Keduanya","Error"]},"answer":0,"explanation":"17 >= 17 bernilai True, jadi blok if yang dijalankan."},{"lesson_id":302,"position":1,"type":"mc","prompt":"Apa output kode berikut?","options":{"code":"x = 7\nif x % 2 == 0:\n    print(\"genap\")\nelse:\n    print(\"ganjil\")","opts":["genap","ganjil","7","Error"]},"answer":1,"explanation":"7 % 2 = 1, bukan 0, jadi blok else yang dijalankan."},{"lesson_id":302,"position":2,"type":"mc","prompt":"Mengapa kode berikut error?","options":{"code":"if 5 > 3\n    print(\"benar\")","opts":["Angkanya salah","Tidak ada titik dua setelah kondisi","print salah tulis","Harus pakai else"]},"answer":1,"explanation":"Setiap baris if harus diakhiri titik dua (:)."},{"lesson_id":303,"position":0,"type":"mc","prompt":"Apa output kode berikut?","options":{"code":"nilai = 60\nif nilai >= 85:\n    print(\"A\")\nelif nilai >= 70:\n    print(\"B\")\nelse:\n    print(\"C\")","opts":["A","B","C","Tidak ada output"]},"answer":2,"explanation":"60 tidak memenuhi >= 85 maupun >= 70, jadi blok else yang dijalankan."},{"lesson_id":303,"position":1,"type":"mc","prompt":"Berapa blok elif yang boleh dipakai dalam satu percabangan?","options":{"opts":["Hanya satu","Maksimal dua","Boleh lebih dari satu","Tidak boleh ada"]},"answer":2,"explanation":"elif boleh dipakai sebanyak yang dibutuhkan."},{"lesson_id":303,"position":2,"type":"mc","prompt":"Apa output kode berikut?","options":{"code":"suhu = 35\nif suhu > 30:\n    print(\"Panas\")\nelif suhu > 20:\n    print(\"Hangat\")\nelse:\n    print(\"Dingin\")","opts":["Panas","Hangat","Panas dan Hangat","Dingin"]},"answer":0,"explanation":"Kondisi pertama sudah True, jadi elif dan else dilewati."},{"lesson_id":304,"position":0,"type":"mc","prompt":"Apa output kode di materi jika hadir = True dan nilai = 60?","options":{"opts":["Lulus","Remedial","Tidak boleh ujian","Error"]},"answer":1,"explanation":"hadir True, lalu nilai 60 < 75, jadi blok else bagian dalam: Remedial."},{"lesson_id":304,"position":1,"type":"mc","prompt":"Apa output kode di materi jika hadir = False dan nilai = 90?","options":{"opts":["Lulus","Remedial","Tidak boleh ujian","Tidak ada output"]},"answer":2,"explanation":"If luar sudah False, jadi if dalam tidak dicek sama sekali."},{"lesson_id":304,"position":2,"type":"mc","prompt":"Kondisi \"hadir dan nilai minimal 75\" bisa ditulis dalam satu if sebagai …","options":{"opts":["if hadir or nilai >= 75:","if hadir and nilai >= 75:","if not hadir:","if nilai >= 75 else hadir:"]},"answer":1,"explanation":"and memastikan kedua kondisi harus benar."},{"lesson_id":401,"position":0,"type":"mc","prompt":"Apa output kode berikut?","options":{"code":"for i in range(3):\n    print(i)","opts":["1 2 3","0 1 2","0 1 2 3","3"]},"answer":1,"explanation":"range(3) menghasilkan 0, 1, 2."},{"lesson_id":401,"position":1,"type":"mc","prompt":"Berapa kali kata \"Halo\" dicetak?","options":{"code":"for i in range(2, 7):\n    print(\"Halo\")","opts":["5","6","7","2"]},"answer":0,"explanation":"range(2, 7) menghasilkan 2, 3, 4, 5, 6, yaitu 5 kali."},{"lesson_id":401,"position":2,"type":"mc","prompt":"Apa output kode berikut?","options":{"code":"total = 0\nfor i in range(1, 5):\n    total = total + i\nprint(total)","opts":["10","15","4","5"]},"answer":0,"explanation":"1 + 2 + 3 + 4 = 10."},{"lesson_id":402,"position":0,"type":"mc","prompt":"Berapa kali kata \"Halo\" dicetak?","options":{"code":"n = 0\nwhile n < 4:\n    print(\"Halo\")\n    n = n + 1","opts":["3","4","5","Tak terbatas"]},"answer":1,"explanation":"n bernilai 0, 1, 2, 3 (4 kali), lalu berhenti saat n = 4."},{"lesson_id":402,"position":1,"type":"mc","prompt":"Apa yang terjadi pada kode berikut?","options":{"code":"x = 1\nwhile x > 0:\n    print(x)","opts":["Mencetak 1 sekali","Tidak mencetak apa-apa","Berjalan terus tanpa henti","Error"]},"answer":2,"explanation":"Nilai x tidak pernah berubah, jadi kondisi selalu True (infinite loop)."},{"lesson_id":402,"position":2,"type":"mc","prompt":"Perulangan yang cocok ketika jumlah pengulangannya belum diketahui adalah …","options":{"opts":["for","while","if","print"]},"answer":1,"explanation":"while berulang selama kondisinya True, jadi cocok saat jumlah putaran belum pasti."},{"lesson_id":403,"position":0,"type":"mc","prompt":"Apa output kode berikut?","options":{"code":"for i in range(5):\n    if i == 2:\n        break\n    print(i)","opts":["0 1","0 1 2","0 1 3 4","2"]},"answer":0,"explanation":"Saat i = 2, break menghentikan perulangan, jadi yang tercetak hanya 0 dan 1."},{"lesson_id":403,"position":1,"type":"mc","prompt":"Apa output kode berikut?","options":{"code":"for i in range(4):\n    if i == 1:\n        continue\n    print(i)","opts":["0 2 3","0 1 2 3","1","0"]},"answer":0,"explanation":"Saat i = 1, continue melewati print, lalu lanjut ke putaran berikutnya."},{"lesson_id":403,"position":2,"type":"mc","prompt":"Perintah untuk menghentikan perulangan sepenuhnya adalah …","options":{"opts":["continue","stop","break","exit"]},"answer":2,"explanation":"break langsung keluar dari perulangan."},{"lesson_id":404,"position":0,"type":"mc","prompt":"Jika nilai yang dimasukkan 80, 70, dan 90, berapa nilai rata?","options":{"opts":["70","80","90","240"]},"answer":1,"explanation":"(80 + 70 + 90) ÷ 3 = 240 ÷ 3 = 80."},{"lesson_id":404,"position":1,"type":"mc","prompt":"Mengapa total diisi 0 sebelum perulangan?","options":{"opts":["Agar program lebih cepat","Sebagai nilai awal sebelum ditambah setiap putaran","Karena Python mewajibkan angka 0","Supaya rata-rata selalu 0"]},"answer":1,"explanation":"total butuh nilai awal. Kalau belum dibuat, total = total + nilai akan error."},{"lesson_id":404,"position":2,"type":"order","prompt":"Susun program yang mencetak bilangan genap dari 1 sampai 10","options":{"blocks":["for i in range(1, 11):","    if i % 2 == 0:","        print(i)"],"pool":[1,2,0]},"answer":[0,1,2],"explanation":"Ulangi 1 sampai 10, cek apakah habis dibagi 2, lalu cetak bilangannya."}]}'::jsonb as j),
lang as (insert into public.languages (id,name,mono,color,accent,description,position)
  select x.id,x.name,x.mono,x.color,x.accent,x.description,x.position from d, jsonb_to_record(d.j->'lang') as x(id text,name text,mono text,color text,accent text,description text,position smallint) returning id),
un as (insert into public.units (id,language_id,title,position)
  select x.id,(select id from lang),x.title,x.position from d, jsonb_to_recordset(d.j->'units') as x(id bigint,title text,position smallint) returning id),
le as (insert into public.lessons (id,unit_id,title,type,duration_min,xp,published,position,material)
  select x.id,x.unit_id,x.title,x.type,x.duration_min,x.xp,x.published,x.position,x.material from d, jsonb_to_recordset(d.j->'lessons') as x(id bigint,unit_id bigint,title text,type text,duration_min smallint,xp smallint,published boolean,position smallint,material jsonb)
  where x.unit_id in (select id from un) returning id)
insert into public.questions (lesson_id,position,type,prompt,options,answer,explanation)
  select x.lesson_id,x.position,x.type,x.prompt,x.options,x.answer,x.explanation from d, jsonb_to_recordset(d.j->'questions') as x(lesson_id bigint,position smallint,type text,prompt text,options jsonb,answer jsonb,explanation text)
  where x.lesson_id in (select id from le);
